package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.net.URI;
import java.net.http.*;
import java.util.*;

final class InboundMailBrowserAcceptance {
 static HttpResponse<String> send(BrowserTest h,String mailbox,String token,Map<String,Object> body)throws Exception{return HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create(h.base()+InboundMailAcceptance.api(mailbox))).header("Authorization","Bearer "+token).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(JSON.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
 static Map<String,Object> delivery(String id,String thread){var b=InboundMailAcceptance.message(id,thread);b.put("recipient","browser-help@opensoft.test");b.put("sender","browser-sender@example.test");b.put("subject","Arrange equipment service <script>");return b;}
 static void run(BrowserTest h)throws Exception {
  String token;try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(String name:List.of("MailBrowserGateway","MailBrowserSender","MailBrowserAgent"))Service.createAccount(db,map("name",name,"role",name.equals("MailBrowserSender")?"requester":"agent","password",WorkflowSupport.PASSWORD));String gateway=RecordAccess.owner(db,"MailBrowserGateway");db.update("UPDATE os_user SET api_only=1 WHERE user_id=?",gateway);db.update("UPDATE os_user SET email='browser-sender@example.test',email_verified=1 WHERE name='MailBrowserSender'");token=ApiKeyWrites.issue(db,db.viewerId,gateway,map("label","Browser mail gateway","table","sc_request","days",1)).get("token").toString();db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var admin=browser.newContext();var requester=browser.newContext();var fulfiller=browser.newContext()){
   var page=admin.newPage();h.login(page,"admin");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Inbound email").setExact(true)).press("Enter");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Configure another mailbox")).press("Enter");page.getByLabel("Receiving mailbox address").fill("browser-help@opensoft.test");page.getByLabel("Allowed sender domain").fill("example.test");page.getByLabel("Gateway account username").fill("MailBrowserGateway");page.getByLabel("Mailbox availability").selectOption("true");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save mailbox configuration")).press("Enter");String mailbox=page.url().substring(page.url().lastIndexOf('/')+1);assertTrue(mailbox.matches("[0-9a-f]{32}"));var response=send(h,mailbox,token,delivery("browser-first",""));assertEquals(200,response.statusCode(),response.body());var first=object(object(JSON.readValue(response.body(),Map.class)).get("result"));String record=object(first.get("record")).get("sys_id").toString(),thread=first.get("thread_id").toString();assertEquals(200,send(h,mailbox,token,delivery("browser-first","")).statusCode());
   var owner=requester.newPage();owner.navigate(h.base()+"/login");owner.getByLabel("Username",new Page.GetByLabelOptions().setExact(true)).fill("MailBrowserSender");owner.getByLabel("Password",new Page.GetByLabelOptions().setExact(true)).fill(WorkflowSupport.PASSWORD);owner.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Enter your workspace")).press("Enter");owner.waitForURL("**/requests");owner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Arrange equipment service <script>").setExact(true)).press("Enter");assertThat(owner.locator("main")).containsText("Please arrange approved service work <script>");var reply=delivery("browser-reply",thread);reply.put("text","The device is available at the front desk <script>");assertEquals(200,send(h,mailbox,token,reply).statusCode());owner.reload();assertThat(owner.locator("main")).containsText("The device is available at the front desk <script>");assertThat(owner.locator("main script")).hasCount(0);owner.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).press("Enter");owner.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(owner);assertEquals(false,owner.evaluate("document.documentElement.scrollWidth>window.innerWidth"));owner.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/inbound-mail-request-dark.png")).setFullPage(true));
   var staff=fulfiller.newPage();h.login(staff,"MailBrowserAgent");staff.navigate(h.base()+"/record/sc_request/"+record);assertThat(staff.locator("main")).containsText("The device is available at the front desk <script>");staff.locator("select[name=state]").selectOption("fulfilling");staff.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save changes →").setExact(true)).press("Enter");assertThat(staff.locator("select[name=state]")).hasValue("fulfilling");page.reload();assertThat(page.locator("main")).containsText("browser-first");assertThat(page.locator("main")).containsText("browser-reply");assertThat(page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Arrange equipment service <script>").setExact(true))).hasCount(2);ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/inbound-mail-receipts-light.png")).setFullPage(true));page.getByLabel("Mailbox availability").selectOption("false");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save mailbox configuration")).press("Enter");assertEquals(403,send(h,mailbox,token,delivery("browser-disabled",thread)).statusCode());assertThat(page.getByLabel("Mailbox availability")).hasValue("false");
  }
 }
}
